/* LightControl: writes P_HeadlightCmd.HeadlightCmd */
Std_ReturnType Rte_Write_P_HeadlightCmd_HeadlightCmd(uint8 data)
{
    return Rte_Sink_LightControl_P_HeadlightCmd_HeadlightCmd(data);
}

/* LightActuator: reads R_HeadlightCmd.HeadlightCmd from buffer Rte_Buf_LightControl_P_HeadlightCmd_HeadlightCmd */
Std_ReturnType Rte_Read_R_HeadlightCmd_HeadlightCmd(uint8 *data)
{
    Std_ReturnType rc;

    if (Rte_Started == FALSE)
    {
        return RTE_E_COM_STOPPED;
    }
    SuspendOSInterrupts();
    *data = Rte_Buf_LightControl_P_HeadlightCmd_HeadlightCmd;
    ResumeOSInterrupts();
    rc = RTE_E_OK;
    return rc;
}

