/* ----------------------------------------------------------------------------------------------
 * Exclusive areas (Rte_Enter / Rte_Exit)
 *   ECUC RteExclusiveAreaImplementation chooses the mechanism: OS_RESOURCE = GetResource/ReleaseResource (priority ceiling:
 *   tasks up to the ceiling cannot preempt the holder, nothing else is blocked); OS_INTERRUPT_BLOCKING / ALL_INTERRUPT_BLOCKING
 *   = Suspend*Interrupts (blocks ISRs too; only for very short sections).
 * ---------------------------------------------------------------------------------------------- */
void Rte_Enter_EA_Odo(void)
{
    (void)GetResource(Res_EA_Odo);   /* ceiling priority 3 = highest priority among tasks that can reach this area */
}

void Rte_Exit_EA_Odo(void)
{
    (void)ReleaseResource(Res_EA_Odo);
}

/* ----------------------------------------------------------------------------------------------
 * Mode handling: Rte_Switch_P_EcuMode_EcuMode (mode manager side)
 *   The mode manager (BswM) requests a mode; the RTE stores it and raises every ModeSwitchEvent whose activation ('ON-ENTRY')
 *   matches the NEW mode. A SWC only observes the mode through Rte_Mode_<p>_<m>() and through its ModeSwitchEvents.
 * ---------------------------------------------------------------------------------------------- */
static const char *Rte_ModeName_EcuMode(Rte_ModeType_EcuMode mode)
{
    const char *n = "?";
    if (mode == RTE_MODE_EcuMode_RUN) { n = "RUN"; }
    if (mode == RTE_MODE_EcuMode_POST_RUN) { n = "POST_RUN"; }
    return n;
}

Std_ReturnType Rte_Switch_P_EcuMode_EcuMode(Rte_ModeType_EcuMode mode)
{
    Rte_ModeType_EcuMode previous;

    if (mode > RTE_MODE_EcuMode_POST_RUN)
    {
        return RTE_E_INVALID;
    }
    SuspendOSInterrupts();            /* tasks read Rte_Mode_EcuMode without a lock: update atomically w.r.t. OS ISRs */
    previous = Rte_Mode_EcuMode;
    Rte_Mode_EcuMode = mode;
    ResumeOSInterrupts();
    TRACE(TRACE_CAT_RTE, "MODE EcuMode=%s", Rte_ModeName_EcuMode(mode));
    if (mode != previous)
    {
        if (mode == RTE_MODE_EcuMode_RUN)
        {
            /* ModeSwitchEvent MSE_LightCtl_EnterRun: on entry of RUN -> Task_LightCtl via SetEvent */
            TRACE(TRACE_CAT_RTE, "TRIGGER MSE_LightCtl_EnterRun -> Task_LightCtl");
            (void)SetEvent(Task_LightCtl, Ev_LightCtl_ModeSwitch);
        }
        else if (mode == RTE_MODE_EcuMode_POST_RUN)
        {
            /* ModeSwitchEvent MSE_LightCtl_EnterPostRun: on entry of POST_RUN -> Task_LightCtl via SetEvent */
            TRACE(TRACE_CAT_RTE, "TRIGGER MSE_LightCtl_EnterPostRun -> Task_LightCtl");
            (void)SetEvent(Task_LightCtl, Ev_LightCtl_ModeSwitch);
        }
    }
    return RTE_E_OK;
}

/* ----------------------------------------------------------------------------------------------
 * Com notification callbacks = the trigger of DataReceivedEvents that come from the network
 *   Com calls Rte_COMCbk_<signal>() after it unpacked a received signal (here from Com_MainFunctionRx, task context, because the
 *   I-PDU is DEFERRED; with IMMEDIATE it would be the CAN RX ISR). The RTE turns that into an OS action: SetEvent on the
 *   extended task that hosts the runnable, or ActivateTask for a basic task. The runnable itself runs later in that task.
 * ---------------------------------------------------------------------------------------------- */
void Rte_COMCbk_VehicleSpeed(void)
{
    if (Rte_Started == FALSE)
    {
        return;                   /* RTE not started: ignore, Rte_Start() establishes a clean state */
    }
    /* DRE_LightCtl_VehicleSpeed (DataReceivedEvent R_VehicleSpeed.VehicleSpeed) -> task Task_LightCtl via SetEvent */
    TRACE(TRACE_CAT_RTE, "TRIGGER DRE_LightCtl_VehicleSpeed -> Task_LightCtl");
    (void)SetEvent(Task_LightCtl, Ev_LightCtl_VehicleSpeed);
}

/* ----------------------------------------------------------------------------------------------
 * Rte_Start / Rte_Stop (SWS 5.7: called by the mode manager, here BswM action AL_Startup after Com_Init)
 * ---------------------------------------------------------------------------------------------- */
Std_ReturnType Rte_Start(void)
{
    /* 1. RTE-internal buffers and implicit buffers -> init values from the ARXML (INIT-VALUE) */
    Rte_Buf_LightControl_P_HeadlightCmd_HeadlightCmd = 0u;
    Rte_Irb_LightCtl_OnSpeed_R_VehicleSpeed_VehicleSpeed = 0u;
    Rte_Pim_LightControl_LightCtl_State = Rte_PimInit_LightControl_LightCtl_State;
    Rte_Pim_LightActuator_Actuator_State = Rte_PimInit_LightActuator_Actuator_State;
    Rte_Pim_Odometer_Odo_State = Rte_PimInit_Odometer_Odo_State;
    /* 2. mode machine starts in the initial mode of the mode declaration group */
    Rte_Mode_EcuMode = RTE_MODE_EcuMode_RUN;
    /* 3. from now on the API works and Com callbacks are honoured */
    Rte_Started = TRUE;
    TRACE(TRACE_CAT_RTE, "START");
    return RTE_E_OK;
}

Std_ReturnType Rte_Stop(void)
{
    Rte_Started = FALSE;
    TRACE(TRACE_CAT_RTE, "STOP");
    return RTE_E_OK;
}
